blocks.solution:
while True:
    num = int(input("Enter a positive number (0 to quit): "))

    if num < 0:
        print("Please enter a positive number.")
        continue
    elif num == 0:
        print("Goodbye!")
        break
    else:
        print(f"You entered: {num}.")
        break

