blocks.solution:
secret = 42

while True:
    guess = int(input("Guess the number: "))

    if guess < secret:
        print("Too low!")
    elif guess > secret:
        print("Too high!")
    else:
        print("Correct! You guessed it!")
        break

problems.solution:
correct_pin = "1234"
max_attempts = 3
attempts = 0

while attempts < max_attempts:
    pin = input("Enter PIN: ")
    attempts += 1
    if pin == correct_pin:
        print("Login successful!")
        break
    else:
        remaining = max_attempts - attempts
        if remaining > 0:
            print(f"Wrong PIN. {remaining} attempts remaining.")
else:
    print("Account locked.")
